SELECT * FROM a_kpi_headline;

-- COMMAND ----------

-- Visualization: Units sold by release year (M) (line: x=release_year, y=global_sales_m)
SELECT release_year, global_sales_m FROM a_sales_by_year ORDER BY release_year;

-- COMMAND ----------

-- Visualization: Top 12 platforms by units sold (M) (hbar: x=platform, y=global_sales_m)
SELECT platform, global_sales_m FROM a_platform_sales ORDER BY global_sales_m DESC LIMIT 12;

-- COMMAND ----------

-- Visualization: Units sold by genre (M) (hbar: x=genre, y=global_sales_m)
SELECT genre, global_sales_m FROM a_genre_region ORDER BY global_sales_m DESC;

-- COMMAND ----------

-- Visualization: Genre share of Japanese sales (%) (hbar: x=genre, y=share_of_jp_pct)
SELECT genre, share_of_jp_pct FROM a_genre_region ORDER BY share_of_jp_pct DESC;

-- COMMAND ----------

-- Visualization: Top 10 publishers by units sold (M) (hbar: x=publisher, y=global_sales_m)
SELECT publisher, global_sales_m FROM a_publisher_top ORDER BY publisher_rank LIMIT 10;

-- COMMAND ----------

-- Visualization: Avg units per title by Metacritic score (M) (bar: x=critic_band, y=avg_sales_m)
SELECT critic_band, avg_sales_m FROM a_critic_score_bands WHERE critic_band <> 'No score' ORDER BY critic_band;
